action.code:
if (hash < 0.0f || hash > 1.0f) {
    throw std::out_of_range("Hash value must be in the range [0, 1]");
}

auto it = partition_to_bucket_.upper_bound(hash);
if (it == partition_to_bucket_.begin()) {
    // If the hash value exceeds all partitions, wrap around to the first bucket
    it = partition_to_bucket_.end();
    --it;
} else {
    --it;  // Point to the bucket responsible for the hash value
}
return it->second;

